CREATE TABLE IF NOT EXISTS game_players(user_id TEXT PRIMARY KEY REFERENCES users(id), payload TEXT NOT NULL, revision INTEGER NOT NULL DEFAULT 0, score INTEGER NOT NULL DEFAULT 0, chores INTEGER NOT NULL DEFAULT 0, dragons INTEGER NOT NULL DEFAULT 0, pin_salt TEXT, pin_hash TEXT);
CREATE TABLE IF NOT EXISTS friend_groups(id TEXT PRIMARY KEY, name TEXT NOT NULL, invite TEXT UNIQUE NOT NULL, owner_id TEXT NOT NULL REFERENCES users(id));
CREATE TABLE IF NOT EXISTS friend_members(group_id TEXT NOT NULL REFERENCES friend_groups(id), user_id TEXT NOT NULL REFERENCES users(id), PRIMARY KEY(group_id,user_id));
